def flatten_list(list1):
    """Write a function to flatten a given nested list structure."""
    result = []
    stack = list(reversed(list1))
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            stack.extend(reversed(item))
        else:
            result.append(item)
    return result
